window.CARDS=window.CARDS||{};CARDS["people-maezono"]=[{"i":"sc-maezono-y1v4_5-p125-1","v":"y1v4.5","y":1,"o":5,"k":"spoken","w":"kushida-kikyou horikita-suzune maezono","q":"maezono ch 4  a passing mention her door opens three rooms from the stairwell  kushida is the one who steps out  kushida had visited her because she had no water and returns her forgotten phone  she sees horikita in the hallway  horikita freezes   you forgot your phone","h":"<article class=\"card\" id=\"sc-maezono-y1v4_5-p125-1\"><h3><span class=\"ttl\">Ch.4: a passing mention<\/span><span class=\"meta\">Y1V4.5 · p.125–127<\/span><\/h3><p class=\"setup\">Her door opens three rooms from the stairwell; Kushida is the one who steps out.<\/p><p class=\"with\">with <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You forgot your phone!”<span class=\"pg\">p.126<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Kushida had visited her because she had no water and returns her forgotten phone.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She sees Horikita in the hallway; Horikita freezes.<span class=\"pg\">p.126<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-maezono-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke maezono","q":"maezono ch 3 sec  3  on the scavenger hunt roster maezono is named by hirata as one of the five picked for the scavenger hunt after the rock paper scissors  picked into the group    ayanokouji kun  yukimura kun  sotomura kun  mori san  and maezono san","h":"<article class=\"card\" id=\"sc-maezono-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 sec. 3: On the scavenger-hunt roster<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><\/h3><p class=\"setup\">Maezono is named by Hirata as one of the five picked for the scavenger hunt after the rock-paper-scissors.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Picked into the group — “Ayanokouji-kun, Yukimura-kun, Sotomura-kun, Mori-san, and Maezono-san.”<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y1v5-p182-1\">→ After: Ch.9 sec. 9: fourth relay leg<\/button><\/div><\/article>"},{"i":"sc-maezono-y1v5-p182-1","v":"y1v5","y":1,"o":6,"k":"","w":"maezono","q":"maezono ch 9 sec  9  fourth relay leg maezono is on the six person relay list and runs fourth  by his handoff class d has fallen to seventh   passing mention   p 182  named on hirata s relay list with hirata  miyake  onodera and sudou  takes the baton with the lead almost gone  passes to kushida with class a already ahead","h":"<article class=\"card\" id=\"sc-maezono-y1v5-p182-1\"><h3><span class=\"ttl\">Ch.9 sec. 9: fourth relay leg<\/span><span class=\"meta\">Y1V5 · p.182–184<\/span><\/h3><p class=\"setup\">Maezono is on the six-person relay list and runs fourth; by his handoff Class D has fallen to seventh. [passing mention] (p.182) Named on Hirata’s relay list with Hirata, Miyake, Onodera and Sudou.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> Takes the baton with the lead almost gone; passes to Kushida with Class A already ahead.<span class=\"pg\">p.184<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y1v5-p39-1\">← Before: Ch.3 sec. 3: On the scavenger-hunt roster<\/button><\/div><\/article>"},{"i":"sc-maezono-y1v9-p141-1","v":"y1v9","y":1,"o":11,"k":"spoken","w":"satou-maya onodera maezono","q":"maezono the absent minded line muttered without a second thought while onodera has not come to school yet   but  sato san doesn t like onodera san very much  does she  the one whose stop attempt comes too late   the secret is out  and the class turns to asking whether anyone has seen them together  so the rumor hardens rather than dies  names onodera by the bare surname in the same breath  printed form is surname only here  absent minded words   narration says they probably came out without a second thought","h":"<article class=\"card\" id=\"sc-maezono-y1v9-p141-1\"><h3><span class=\"ttl\">The absent-minded line<\/span><span class=\"meta\">Y1V9 · p.141<\/span><\/h3><p class=\"setup\">Muttered without a second thought while Onodera has not come to school yet.<\/p><p class=\"with\">with <a href=\"satou-maya.html\">Satō Maya<\/a> · <a href=\"onodera.html\">Onodera<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“But… Satō-san doesn’t like Onodera-san very much, does she?”<span class=\"pg\">p.141<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Satō Maya<\/b> The one whose stop attempt comes too late — the secret is out, and the class turns to asking whether anyone has seen them together, so the rumor hardens rather than dies.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Onodera<\/b> Names Onodera by the bare surname in the same breath; printed form is surname only here.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Absent-minded words — narration says they probably came out without a second thought.<span class=\"pg\">p.141<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-maezono-y2v2-p12-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"maezono","q":"maezono maezono sides with kei in the classroom argument she backs karuizawa against yukimura during the heated exchange over ayanokoji s perfect score   yeah  yeah  isn t it weird that you re taking your anger out on karuizawa san  quick to defend her friends in a dispute","h":"<article class=\"card\" id=\"sc-maezono-y2v2-p12-1\"><h3><span class=\"ttl\">Maezono sides with Kei in the classroom argument<\/span><span class=\"meta\">Y2V2 · p.12–22<\/span><\/h3><p class=\"setup\">She backs Karuizawa against Yukimura during the heated exchange over Ayanokōji&#x27;s perfect score.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Yeah, yeah! Isn&#x27;t it weird that you&#x27;re taking your anger out on Karuizawa-san?&quot;<span class=\"pg\">p.17<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Quick to defend her friends in a dispute.<span class=\"pg\">p.17<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-maezono-y2v5-p22-1","v":"y2v5","y":2,"o":21,"k":"action spoken","w":"satou-maya horikita-suzune ayanokouji-kiyotaka maezono","q":"maezono maezono on guard duty at the maid cafe demonstration posted at the special wing classroom guarding the maid cafe demonstration  a rented room with shaded windows against third parties   oh  i m on guard duty  i don t think there s anyone coming to the special wing after school  but i had to make sure  waves happily to horikita and ayanokoji as they leave  the room s commotion must have reached his ears   i m kind of surprised how well that went   i m kind of surprised how well that went  is untagged  adjacent narration  maezono  who had been watching us  waved happily at us  supports him as the speaker  the reply is equally untagged and probably horikita s  neither speaker is name tagged in the print  co planner of the maid cafe  standing guard for her team  guards her demonstration site  waves them off  lets him in as a customer  waves him out","h":"<article class=\"card\" id=\"sc-maezono-y2v5-p22-1\"><h3><span class=\"ttl\">Maezono on guard duty at the maid-café demonstration<\/span><span class=\"meta\">Y2V5 · p.22–25<\/span><\/h3><p class=\"setup\">Posted at the special-wing classroom guarding the maid-café demonstration; a rented room with shaded windows against third parties.<\/p><p class=\"with\">with <a href=\"satou-maya.html\">Satō Maya<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Oh, I&#x27;m on guard duty. I don&#x27;t think there&#x27;s anyone coming to the special wing after school, but I had to make sure.&quot;<span class=\"pg\">p.22<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m kind of surprised how well that went.&quot;<span class=\"pg\">p.25<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Waves happily to Horikita and Ayanokōji as they leave; the room&#x27;s commotion must have reached his ears.<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> &quot;I&#x27;m kind of surprised how well that went.&quot; is untagged; adjacent narration (&quot;Maezono, who had been watching us, waved happily at us&quot;) supports him as the speaker; the reply is equally untagged and probably Horikita&#x27;s; neither speaker is name-tagged in the print.<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Satō Maya<\/b> Co-planner of the maid café; standing guard for her team.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Guards her demonstration site; waves them off.<span class=\"pg\">p.22–25<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Lets him in as a customer; waves him out.<span class=\"pg\">p.22, 25<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v5-p93-1\">→ After: Maezono: the Hokkaido spearhead<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v5-p93-1","v":"y2v5","y":2,"o":21,"k":"spoken","w":"maezono","q":"maezono maezono  the hokkaido spearhead  wait a minute  i ll admit that okinawa is one of the standard places  but if you say that  then so is the north coast highway  it s not even a close call in terms of votes  don t you want to go skiing or something  women s team spearhead    the hokkaido team  spearheaded by maezono  middleweight ishikura  and general shinohara  this is a women s team    beats onodera in the first game  ski or nothing   argues hokkaido s merits on snow logic  not ocean logic","h":"<article class=\"card\" id=\"sc-maezono-y2v5-p93-1\"><h3><span class=\"ttl\">Maezono: the Hokkaido spearhead<\/span><span class=\"meta\">Y2V5 · p.93–96<\/span><\/h3><p class=\"setup\">Women&#x27;s team spearhead — &quot;The Hokkaido team, spearheaded by Maezono, middleweight Ishikura, and general Shinohara. This is a women&#x27;s team.&quot; — beats Onodera in the first game.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Wait a minute. I&#x27;ll admit that Okinawa is one of the standard places, but if you say that, then so is the North Coast Highway. It&#x27;s not even a close call in terms of votes. Don&#x27;t you want to go skiing or something?&quot;<span class=\"pg\">p.93<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Ski-or-nothing — argues Hokkaido&#x27;s merits on snow logic, not ocean logic.<span class=\"pg\">p.93–96<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v5-p22-1\">← Before: Maezono on guard duty at the maid-café demonstration<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v6-p11-1","v":"y2v6","y":2,"o":22,"k":"","w":"maezono","q":"maezono maezono mentioned in passing named in this volume  passing mentions on pages  p 58  p 60  passing mention only","h":"<article class=\"card\" id=\"sc-maezono-y2v6-p11-1\"><h3><span class=\"ttl\">maezono mentioned in passing<\/span><span class=\"meta\">Y2V6 · p.11-346<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.58, p.60.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-maezono-y2v7-p11-1","v":"y2v7","y":2,"o":23,"k":"spoken","w":"maezono","q":"maezono the equal sales question answered after horikita s tie question  maezono doubts the scenario is worth worrying about   i don t think an equal number of sales among the classes would be normal  i don t think you need to worry about it    maezono voiced her doubts  chabashira agrees it s not a bad thing to know the rule  horikita had a point  maezono s worry is that an equal sales tie is not realistic","h":"<article class=\"card\" id=\"sc-maezono-y2v7-p11-1\"><h3><span class=\"ttl\">The equal-sales question answered<\/span><span class=\"meta\">Y2V7 · p.11<\/span><\/h3><p class=\"setup\">After Horikita&#x27;s tie question; Maezono doubts the scenario is worth worrying about.<\/p><ul class=\"lines\"><li class=\"q spoken\">“I don&#x27;t think an equal number of sales among the classes would be normal. I don&#x27;t think you need to worry about it.” — Maezono voiced her doubts.<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Chabashira agrees it&#x27;s not a bad thing to know the rule; Horikita had a point; Maezono&#x27;s worry is that an equal-sales tie is not realistic.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v7-p13-1\">→ After: Maid café planning: stall location and budget debate<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v7-p13-1","v":"y2v7","y":2,"o":23,"k":"spoken","w":"maezono","q":"maezono maid cafe planning  stall location and budget debate the six planners inspect special building stall floors  maezono argues for the first floor  the group votes by rock paper scissors  first floor wins   i guess the second floor is better than the third floor  more to the point  the first floor would be ideal    maezono muttered as she looked at the view outside the window  the five candidates  first through third floors  the third floor could be rented for between 1 000 and 13 000 points  the first floor flat 50 000   the nearly 40 000 point difference could be used to purchase food and other necessities  the vote  four rocks  first floor  two papers  ayanokoji  matsushita  zero scissors  third floor eliminated for time and effort  horikita applied for the first floor by phone   does that mean a maid cafe    maezono immediately responds to the keyword  same  when ryuen declares the same concept   maezono who immediately responded to the keyword  same    she is the canary in the planners  cage","h":"<article class=\"card\" id=\"sc-maezono-y2v7-p13-1\"><h3><span class=\"ttl\">Maid café planning: stall location and budget debate<\/span><span class=\"meta\">Y2V7 · p.13–22<\/span><\/h3><p class=\"setup\">The six planners inspect special-building stall floors; Maezono argues for the first floor; the group votes by rock-paper-scissors; first floor wins.<\/p><ul class=\"lines\"><li class=\"q spoken\">“I guess the second floor is better than the third floor! More to the point, the first floor would be ideal,” — Maezono muttered as she looked at the view outside the window.<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\">“Does that mean a maid café?” — Maezono immediately responds to the keyword “same.”<span class=\"pg\">p.29<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The five candidates: first through third floors; the third floor could be rented for between 1,000 and 13,000 points; the first floor flat 50,000; “the nearly 40,000 point difference could be used to purchase food and other necessities.”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The vote: four rocks (first floor), two papers (Ayanokōji, Matsushita), zero scissors; third floor eliminated for time and effort; Horikita applied for the first floor by phone.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> When Ryūen declares the same concept, “Maezono who immediately responded to the keyword &#x27;same&#x27;” — she is the canary in the planners&#x27; cage.<span class=\"pg\">p.29<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v7-p11-1\">← Before: The equal-sales question answered<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v7-p27-1\">→ After: The leak hits; Maezono confronts Horikita; the concept collapse<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v7-p27-1","v":"y2v7","y":2,"o":23,"k":"spoken","w":"horikita-suzune ike-kanji ryuuen-kakeru maezono","q":"maezono the leak hits  maezono confronts horikita  the concept collapse maezono stood up in surprise when ike burst in with the leaked maid cafe news   a secret kept from all but a few students   where did you hear this  ike san    maezono  stiff and angry  ike choked on his words   does this mean that ryuen kun betrayed us after all  you said it was okay  didn t you  horikita san    maezono angrily confronts horikita  maezono  in particular  was glaring at ryuen without hiding her annoyance   what are you going to do  horikita san  we re pretty well prepared  aren t we    matsushita asked  maezono and the others approached horikita  letting some of the bottled up anxiety and frustration spill out   we can t do that  part of the budget s already invested    horikita answers  the planners are trapped between the sunken budget and the copied concept  she confronts horikita over the ryuen betrayal  anxiety and frustration spill out  he brings the lobby rumor  she frightens him with her angry look  his leak turns her open hostility public  she glares without hiding it","h":"<article class=\"card\" id=\"sc-maezono-y2v7-p27-1\"><h3><span class=\"ttl\">The leak hits; Maezono confronts Horikita; the concept collapse<\/span><span class=\"meta\">Y2V7 · p.27–31<\/span><\/h3><p class=\"setup\">Maezono stood up in surprise when Ike burst in with the leaked maid café news — a secret kept from all but a few students.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Where did you hear this, Ike-san?” — Maezono, stiff and angry; Ike choked on his words.<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\">“Does this mean that Ryūen-kun betrayed us after all? You said it was okay, didn&#x27;t you, Horikita-san?” — Maezono angrily confronts Horikita.<span class=\"pg\">p.27–28<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Maezono, in particular, was glaring at Ryūen without hiding her annoyance.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “What are you going to do, Horikita-san? We&#x27;re pretty well prepared, aren&#x27;t we..?” — Matsushita asked; Maezono and the others approached Horikita, letting some of the bottled-up anxiety and frustration spill out.<span class=\"pg\">p.30–31<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “We can&#x27;t do that. Part of the budget&#x27;s already invested.” — Horikita answers; the planners are trapped between the sunken budget and the copied concept.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She confronts Horikita over the Ryūen betrayal; anxiety and frustration spill out.<span class=\"pg\">p.27–31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> He brings the lobby rumor; she frightens him with her angry look.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> His leak turns her open hostility public; she glares without hiding it.<span class=\"pg\">p.27–29<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v7-p13-1\">← Before: Maid café planning: stall location and budget debate<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v7-p84-1\">→ After: The early departure; four booths<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v7-p84-1","v":"y2v7","y":2,"o":23,"k":"spoken","w":"hasebe-haruka miyake-akito kouenji-rokusuke satou-maya maezono","q":"maezono the early departure  four booths the day before the festival  maezono asks about hasebe and miyake leaving the classroom  four booths in horikita s class   you guys didn t make hasebe san and miyake kun come    maezono asked as her eyes followed haruka and akito leaving  the four booths  the maid cafe  main sales  tea  coffee  and other drinks  plus photo shoots with the maids  two outdoor stalls  powdered food   takoyaki  okonomiyaki   and western style pasta and bread stalls  and the outdoor quiz competition for children  added on short notice with the extra budget  35 people  excluding koenji  hasebe and miyake  were left alone to run the rehearsal  she left early   potentially planning revenge  he left with her  the only other non cooperator  along with hasebe and miyake  the rehearsal proceeds with her and the other planners","h":"<article class=\"card\" id=\"sc-maezono-y2v7-p84-1\"><h3><span class=\"ttl\">The early departure; four booths<\/span><span class=\"meta\">Y2V7 · p.84<\/span><\/h3><p class=\"setup\">The day before the festival; Maezono asks about Hasebe and Miyake leaving the classroom; four booths in Horikita&#x27;s class.<\/p><p class=\"with\">with <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"miyake-akito.html\">Miyake Akito<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"satou-maya.html\">Satō Maya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You guys didn&#x27;t make Hasebe-san and Miyake-kun come?” — Maezono asked as her eyes followed Haruka and Akito leaving.<span class=\"pg\">p.84<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The four booths: the maid café (main sales: tea, coffee, and other drinks, plus photo shoots with the maids); two outdoor stalls (powdered food — takoyaki, okonomiyaki — and Western-style pasta and bread stalls); and the outdoor quiz competition for children, added on short notice with the extra budget.<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> 35 people, excluding Kōenji, Hasebe and Miyake, were left alone to run the rehearsal.<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> She left early — potentially planning revenge.<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Miyake Akito<\/b> He left with her.<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> The only other non-cooperator, along with Hasebe and Miyake.<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Satō Maya<\/b> The rehearsal proceeds with her and the other planners.<span class=\"pg\">p.84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v7-p27-1\">← Before: The leak hits; Maezono confronts Horikita; the concept collapse<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v7-p190-1\">→ After: The planner high-five<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v7-p190-1","v":"y2v7","y":2,"o":23,"k":"","w":"maezono","q":"maezono the planner high five  the three of them high fived each other    sato  mii chan  maezono  they celebrate the festival victory  maezono is the third high fiv er  she says nothing on record here","h":"<article class=\"card\" id=\"sc-maezono-y2v7-p190-1\"><h3><span class=\"ttl\">The planner high-five<\/span><span class=\"meta\">Y2V7 · p.190<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The three of them high-fived each other.” — Satō, Mii-chan, Maezono; they celebrate the festival victory.<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Maezono is the third high-fiv-er; she says nothing on record here.<span class=\"pg\">p.190<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v7-p84-1\">← Before: The early departure; four booths<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v9_5-p66-1","v":"y2v9.5","y":2,"o":26,"k":"spoken","w":"ayanokouji-kiyotaka matsushita-chiaki ike-kanji maezono","q":"maezono maezono  the secret meeting to size up ayanokoji she gathers a small group  ike  sudo  shinohara  matsushita  mori  wang  maezono  onodera  at keyaki mall  deliberately excluding karuizawa and her close friends  and opens the discussion of ayanokoji   whom she says she dislikes as  dark and hard to get along with   to be honest  perhaps it s problematic for me to say this  but i don t like   that s true  but i don t like dark and hard to get along with people  i feel  she argues his oaa understates his real ability  he solved hard questions in the special exam  was fast in the relay  is a strategic threat  warns that he named sakura for expulsion  and opposes making him the class s leader   though she cannot name an alternative   i heard this from someone else  but  during the uninhabited island exam   i strongly oppose ayanokoji kun being the leader  perceptive and outspoken   she sees through ayanokoji s facade and organizes the meeting to decide how the class should treat him  but remains evasive when asked for her own preferred leader  the subject of the meeting  she senses he is  hiding  something  co organizer who agrees with her  defends ayanokoji  she challenges him sharply","h":"<article class=\"card\" id=\"sc-maezono-y2v9_5-p66-1\"><h3><span class=\"ttl\">Maezono: the secret meeting to size up Ayanokōji<\/span><span class=\"meta\">Y2V9.5 · p.66–80<\/span><\/h3><p class=\"setup\">She gathers a small group (Ike, Sudō, Shinohara, Matsushita, Mori, Wang, Maezono, Onodera) at Keyaki Mall, deliberately excluding Karuizawa and her close friends, and opens the discussion of Ayanokōji — whom she says she dislikes as &quot;dark and hard-to-get-along-with.&quot; She argues his OAA understates his real ability (he solved hard questions in the special exam, was fast in the relay, is a strategic threat), warns that he named Sakura for expulsion, and opposes making him the class&#x27;s leader — though she cannot name an alternative.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"matsushita-chiaki.html\">Matsushita Chiaki<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;To be honest, perhaps it&#x27;s problematic for me to say this, but I don&#x27;t like...&quot;<span class=\"pg\">p.68<\/span><\/li><li class=\"q spoken\">&quot;That&#x27;s true, but I don&#x27;t like dark and hard-to-get-along-with people... I feel&quot;<span class=\"pg\">p.68<\/span><\/li><li class=\"q spoken\">&quot;I heard this from someone else, but... during the uninhabited island exam&quot;<span class=\"pg\">p.73<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I strongly oppose Ayanokōji-kun being the leader.&quot;<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Perceptive and outspoken — she sees through Ayanokōji&#x27;s facade and organizes the meeting to decide how the class should treat him, but remains evasive when asked for her own preferred leader.<span class=\"pg\">p.66–80<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The subject of the meeting; she senses he is &quot;hiding&quot; something.<span class=\"pg\">p.68–79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matsushita Chiaki<\/b> Co-organizer who agrees with her.<span class=\"pg\">p.66<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Defends Ayanokōji; she challenges him sharply.<span class=\"pg\">p.69–72<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-maezono-y2v10-p46-1","v":"y2v10","y":2,"o":28,"k":"spoken","w":"horikita-suzune hirata-yousuke kushida-kikyou maezono","q":"maezono ch 2  maezono s challenge raises her hand despite hesitating as the class drifts toward horikita as leader   hold on a second   i think there may be a little room for discussion  appeals to the room  including yosuke  her point  the unanimous vote exam s expulsion decision is the template for leader decisions   certainly  i think horikita san is reliable  it s greatly appreciated that she s willing to take on such a responsible role as a leader  however  we can t afford to lose this special exam  right  if we rank last and have an elimination  that person will be expelled from class  therefore  shouldn t we appoint the person who would give us the highest chance of winning as the leader   i don t doubt horikita san s abilities at all  but is she really the best option  i think there s some room for discussion  can t we find someone who can make better decisions in the class   calm down  it s just my personal opinion  but can i mention it   during the unanimous vote special exam  horikita san changed her opinion due to the flow of kushida san s expulsion  right  the person who should ve taken responsibility at that time should ve been a student who continued to vote against it  but i just have a feeling that she didn t stick to it where she should have  this time  the leader decides everything  right  the rest of her printed speech  choosing who to expel   kushida san is still in the class is a big plus  continues on the same page  quoted in part  presses for alternatives   recommendations  she is told to meet the same standard   a raised hand or silence   even if no one has come forward  there may still be recommendations  if you ask other people  including myself  they may be able to give you more suitable candidates  isn t it worth asking   but  her line is the formal withdrawal   certainly  as horikita san said  we can t make someone who doesn t nominate themselves a leader  the pages show her  unable to come up with a counterargument and stuttered  at this point  her actual hand stays down  questions her decisiveness in public  withdraws when the class asks for volunteers instead  he weathers her challenge with a smile  she respects the question enough to press it  uses the kushida expulsion flow as her exhibit","h":"<article class=\"card\" id=\"sc-maezono-y2v10-p46-1\"><h3><span class=\"ttl\">Ch.2: Maezono&#x27;s challenge<\/span><span class=\"meta\">Y2V10 · p.46–49<\/span><\/h3><p class=\"setup\">Raises her hand despite hesitating as the class drifts toward Horikita-as-leader. Appeals to the room, including Yōsuke; her point: the unanimous-vote exam&#x27;s expulsion decision is the template for leader decisions. Presses for alternatives: &quot;recommendations&quot;; she is told to meet the same standard — a raised hand or silence. Her line is the formal withdrawal.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hold on a second!”<span class=\"pg\">p.46<\/span><\/li><li class=\"q spoken\">“I think there may be a little room for discussion...”<span class=\"pg\">p.46<\/span><\/li><li class=\"q spoken\">“Certainly, I think Horikita-san is reliable. It’s greatly appreciated that she’s willing to take on such a responsible role as a leader. However... we can’t afford to lose this special exam, right? If we rank last and have an…”<span class=\"pg\">p.47<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Certainly, I think Horikita-san is reliable. It’s greatly appreciated that she’s willing to take on such a responsible role as a leader. However... we can’t afford to lose this special exam, right? If we rank last and have an elimination, that person will be expelled from class. Therefore, shouldn’t we appoint the person who would give us the highest chance of winning as the leader?”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t doubt Horikita-san’s abilities at all. But is she really the best option? I think there’s some room for discussion. Can’t we find someone who can make better decisions in the class?”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Calm down. It’s just my personal opinion, but can I mention it?”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “During the unanimous vote special exam, Horikita-san changed her opinion due to the flow of Kushida-san’s expulsion, right? The person who should’ve taken responsibility at that time should’ve been a student who continued to vote against it. But I just have a feeling that she didn’t stick to it where she should have. This time, the leader decides everything, right?”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The rest of her printed speech (choosing who to expel; &quot;Kushida-san is still in the class is a big plus&quot;) continues on the same page; quoted in part.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if no one has come forward, there may still be recommendations. If you ask other people, including myself, they may be able to give you more suitable candidates. Isn’t it worth asking?”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But—”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Certainly, as Horikita-san said, we can’t make someone who doesn’t nominate themselves a leader.”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The pages show her &quot;unable to come up with a counterargument and stuttered&quot; at this point; her actual hand stays down.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Questions her decisiveness in public; withdraws when the class asks for volunteers instead.<span class=\"pg\">p.46–49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> He weathers her challenge with a smile; she respects the question enough to press it.<span class=\"pg\">p.46–47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Uses the Kushida expulsion flow as her exhibit.<span class=\"pg\">p.47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v10-p47-1\">→ After: Ch.2: Maezono questions Horikita<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v10-p47-1","v":"y2v10","y":2,"o":28,"k":"spoken","w":"horikita-suzune kushida-kikyou maezono","q":"maezono ch 2  maezono questions horikita goes straight to the heart of it  the unanimous vote exam  horikita wavered  that was a decisive failure point  now the leader is once again the sole decision maker  reinforces that horikita is untested  presses  asks who else might be better  suggests asking around  she withdraws after koenji is proposed  and horikita s counter offer is convincing   i don t doubt horikita san s abilities at all  but is she really the best option  i think there s some room for discussion  directly challenges her decisiveness  uses her survival as a check point","h":"<article class=\"card\" id=\"sc-maezono-y2v10-p47-1\"><h3><span class=\"ttl\">Ch.2: Maezono questions Horikita<\/span><span class=\"meta\">Y2V10 · p.47–49<\/span><\/h3><p class=\"setup\">Goes straight to the heart of it: the unanimous vote exam; Horikita wavered; that was a decisive failure point; now the leader is once again the sole decision-maker; reinforces that Horikita is untested. Presses; asks who else might be better; suggests asking around; she withdraws after Kōenji is proposed (and Horikita&#x27;s counter-offer is convincing).<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I don&#x27;t doubt Horikita-san&#x27;s abilities at all. But is she really the best option? I think there&#x27;s some room for discussion.&quot;<span class=\"pg\">p.47<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Directly challenges her decisiveness.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Uses her survival as a check point.<span class=\"pg\">p.47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v10-p46-1\">← Before: Ch.2: Maezono&#x27;s challenge<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v10-p81-1\">→ After: Ch.4: Ike&#x27;s &quot;fake illness&quot; strategy — rejected<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v10-p81-1","v":"y2v10","y":2,"o":28,"k":"spoken","w":"keisei-ishigami horikita-suzune maezono","q":"maezono ch 4  ike s  fake illness  strategy   rejected ike declares he has a winning strategy that will give 68 points  it means faking illness  horikita instantly grasps  if caught  the school can t prove it   too perfect  bursts from ike  horikita explains the loophole  if ryuen ran this exact strategy  the three other classes would surely conspire to earn  67  he d lose and be expelled  ike deflates  horikita praises ike s bravery for speaking up  he thaws  suggestion that everyone should pitch in  no one has anything else   dude  i think  i might have an incredible winning strategy   while it s risky  we could secure exactly 68 points  we do this by feigning sickness right as the exam starts   i think you understand which is better  aiming for a win with 66 points or securing 17 or more points in 10 turns with your own abilities  the 68 point strategy nearly worked  but horikita punted   concerns about sakayanagi and ryuen conspiring against ryuen  won t work if everyone targets them  listens without premature judgment  peers of her instruction","h":"<article class=\"card\" id=\"sc-maezono-y2v10-p81-1\"><h3><span class=\"ttl\">Ch.4: Ike&#x27;s &quot;fake illness&quot; strategy — rejected<\/span><span class=\"meta\">Y2V10 · p.81–89<\/span><\/h3><p class=\"setup\">Ike declares he has a winning strategy that will give 68 points; it means faking illness; Horikita instantly grasps; if caught, the school can&#x27;t prove it; &quot;too perfect!&quot; bursts from Ike. Horikita explains the loophole: if Ryūen ran this exact strategy, the three other classes would surely conspire to earn &gt;67; he&#x27;d lose and be expelled; Ike deflates. Horikita praises Ike&#x27;s bravery for speaking up; he thaws; suggestion that everyone should pitch in; no one has anything else.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Dude... I think... I might have an incredible winning strategy...!&quot;<span class=\"pg\">p.81<\/span><\/li><li class=\"q spoken\">&quot;While it’s risky, we could secure exactly 68 points. We do this by feigning sickness right as the exam starts.&quot;<span class=\"pg\">p.83<\/span><\/li><li class=\"q spoken\">&quot;I think you understand which is better, aiming for a win with 66 points or securing 17 or more points in 10 turns with your own abilities.&quot;<span class=\"pg\">p.87<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">keisei-ishigami<\/b> The 68-point strategy nearly worked, but Horikita punted — concerns about Sakayanagi and Ryūen conspiring against Ryūen (won&#x27;t work if everyone targets them).<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Listens without premature judgment; peers of her instruction.<span class=\"pg\">p.81–89<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v10-p47-1\">← Before: Ch.2: Maezono questions Horikita<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v10-p120-1\">→ After: Ch.5: The Maezono reveal<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v10-p120-1","v":"y2v10","y":2,"o":28,"k":"","w":"maezono","q":"maezono ch 5  the maezono reveal passing mention  sakayanagi asks   are you dating maezono san for information  not love    hashimoto s covers are blown  she saw him openly dating maezono several times  passing mention   the audio data regarding the ayanokoji  threat discussion  that you shared with masumi san  was prepared by her  wasn t it    the threat discussion audio came from maezono herself  the pages reveal the maezono hashimoto pairing as a working relationship with unclear boundaries  sakayanagi treats it as an open secret","h":"<article class=\"card\" id=\"sc-maezono-y2v10-p120-1\"><h3><span class=\"ttl\">Ch.5: The Maezono reveal<\/span><span class=\"meta\">Y2V10 · p.120–121<\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Passing mention: Sakayanagi asks, &quot;Are you dating Maezono-san for information, not love?&quot; — Hashimoto&#x27;s covers are blown; she saw him openly dating Maezono several times.<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention: &quot;The audio data regarding the Ayanokōji &#x27;threat discussion&#x27; that you shared with Masumi-san, was prepared by her, wasn’t it?&quot; — the threat-discussion audio came from Maezono herself.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The pages reveal the Maezono–Hashimoto pairing as a working relationship with unclear boundaries; Sakayanagi treats it as an open secret.<span class=\"pg\">p.120<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v10-p81-1\">← Before: Ch.4: Ike&#x27;s &quot;fake illness&quot; strategy — rejected<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v12-p159-1","v":"y2v12","y":2,"o":31,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi maezono","q":"maezono ch 7  the traitor who leaked she sits in the interrogation room opposite ayanokoji   the traitor room  says  is it my turn this time  he tells her he is lost about who the traitor is  randomly calling classmates   is it my turn this time  he asks her to formally confirm she is not the traitor    maezono  you re not the traitor  right    she says she is not  then she hesitates and looks at him with eyes full of rage   right  for the sake of progress  let me formally confirm things   hey  if i was the traitor and was found lying  what would happen to you  asked why she leaked it  she confesses   she was in the gathering of  a few of our classmates  spread unsettling information about him  and passed it to hashimoto  she named him  he d pressured her   masayoshi  i told masayoshi   i understand  but  but this information wasn t even that important  he tells her that even hashimoto wants obedience more than truth  he knows her type  she swears she won t do it again  he asks her to confess formally  she denies everything   i wouldn t do that  there s no way i would   okay  okay  i get it  i absolutely won t do anything like that anymore  he declares her guilty of being the traitor  expulsion is handed down  she screams she won t leave until he takes it back  she chases after him  the examiners stop her at the door   she is expelled   no  i won t leave until you take it back   take it back  take it back right now   i will never forgive you  her expulsion is real  recorded in the official announcement  the exam staff seemed unwilling to let this route be used  the line  this special exam was hastily  is cut off on page   the special circumstances are withheld from the reader  the man who owned her   she leaked for him  she is discarded the moment she loses value  the man she called to evaluate her   he evaluates her and she is expelled for owing someone loyalty","h":"<article class=\"card\" id=\"sc-maezono-y2v12-p159-1\"><h3><span class=\"ttl\">Ch.7: The traitor who leaked<\/span><span class=\"meta\">Y2V12 · p.159–167<\/span><\/h3><p class=\"setup\">She sits in the interrogation room opposite Ayanokōji — the traitor room; says “Is it my turn this time?”; he tells her he is lost about who the traitor is, randomly calling classmates. He asks her to formally confirm she is not the traitor — “Maezono, you’re not the traitor, right?” — she says she is not; then she hesitates and looks at him with eyes full of rage. Asked why she leaked it, she confesses — she was in the gathering of “a few of our classmates,” spread unsettling information about him, and passed it to Hashimoto; she named him; he&#x27;d pressured her. He tells her that even Hashimoto wants obedience more than truth; he knows her type; she swears she won&#x27;t do it again; he asks her to confess formally; she denies everything. He declares her guilty of being the traitor; expulsion is handed down; she screams she won&#x27;t leave until he takes it back; she chases after him; the examiners stop her at the door — she is expelled.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Is it my turn this time?”<span class=\"pg\">p.159<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Right. For the sake of progress, let me formally confirm things.”<span class=\"pg\">p.160<\/span><\/li><li class=\"q spoken\">“…Hey, if I was the traitor and was found lying, what would happen to you?”<span class=\"pg\">p.160<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Masayoshi! I told Masayoshi!”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand, but… but this information wasn’t even that important!”<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wouldn’t do that! There’s no way I would!”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Okay, okay, I get it! I absolutely won’t do anything like that anymore!”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No! I won’t leave until you take it back!”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Take it back! Take it back right now!”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I will never forgive you!!”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her expulsion is real (recorded in the official announcement); the exam staff seemed unwilling to let this route be used; the line “this special exam was hastily…” is cut off on-page — the special circumstances are withheld from the reader.<span class=\"pg\">p.166–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> The man who owned her — she leaked for him; she is discarded the moment she loses value.<span class=\"pg\">p.162–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The man she called to evaluate her — he evaluates her and she is expelled for owing someone loyalty.<span class=\"pg\">p.159–167<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v12-p169-1\">→ After: Mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v12-p169-1","v":"y2v12","y":2,"o":31,"k":"","w":"maezono","q":"maezono mentioned in passing named in passing    i could take that material away  by helping you  my credibility inevitably increased  named in passing    even the matter of maezono s expulsion now seemed like a distant past  almost obscured  passing mention only  her expulsion is recorded in full in her own entry   this section covers only the direct references","h":"<article class=\"card\" id=\"sc-maezono-y2v12-p169-1\"><h3><span class=\"ttl\">Mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.169–170<\/span><\/h3><p class=\"setup\">Named in passing — “I could take that material away. By helping you, my credibility inevitably increased.” Named in passing — “Even the matter of Maezono’s expulsion now seemed like a distant past, almost obscured.”<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only; her expulsion is recorded in full in her own entry — this section covers only the direct references.<span class=\"pg\">p.169–170<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-maezono-y2v12-p159-1\">← Before: Ch.7: The traitor who leaked<\/button><\/div><\/article>"},{"i":"sc-maezono-y2v12_5-p11-1","v":"y2v12.5","y":2,"o":32,"k":"","w":"maezono","q":"maezono maezono mentioned in passing named in this volume  passing mention  locator pages  p 10 21  p 24 26  p 32  p 56  p 63 64  p 80 82  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-maezono-y2v12_5-p11-1\"><h3><span class=\"ttl\">maezono mentioned in passing<\/span><span class=\"meta\">Y2V12.5 · p.11-216<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.10-21, p.24-26, p.32, p.56, p.63-64, p.80-82; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><\/article>"}];
